// Keep the original behavior: only include public repos with a description and language.
const repositories = [];
for (const item of $input.all()) {
  const data = item.json;
  const repos = Array.isArray(data) ? data : (Array.isArray(data.body) ? data.body : [data]);
  for (const repo of repos) {
    if (
      typeof repo.description !== 'string' || !repo.description.trim() ||
      typeof repo.language !== 'string' || !repo.language.trim()
    ) continue;
    repositories.push({ json: {
      name: repo.name,
      description: repo.description,
      languages: [repo.language]
    }});
  }
}
return repositories;

// Manually maintained repositories not returned by the public GitHub endpoint.
const repositories = [
  {
    name: "Magistra3.0",
    description: "Private information hub built with Spring Boot, SQLite, WebSockets and data connectors.",
    languages: ["Java", "JavaScript", "SQL"]
  },
  {
    name: "TraceAI",
    description: "AI-based project for data processing, analysis and intelligent retrieval.",
    languages: ["Python"]
  },
  {
    name: "RAG-Project",
    description: "Retrieval-Augmented Generation project combining vector search, Neo4j graph relationships and AI agents.",
    languages: ["Python", "JavaScript"]
  },
  {
    name: "Self-Hosted-AI",
    description: "Self-hosted AI environment integrating local language models, n8n automation, PostgreSQL and Qdrant.",
    languages: ["Python", "JavaScript", "SQL"]
  }
];
return repositories.map(repo => ({ json: repo }));

// Shared preparation stage. Both RAG branches start from this exact normalized dataset.
const byName = new Map();
for (const item of $input.all()) {
  const repo = item.json || {};
  if (!repo.name) continue;
  const name = String(repo.name).trim();
  const description = typeof repo.description === 'string' ? repo.description.trim() : '';
  const languages = Array.isArray(repo.languages)
    ? repo.languages.filter(x => typeof x === 'string' && x.trim())
    : [];
  const existing = byName.get(name);
  if (!existing) byName.set(name, {name, description, languages: [...new Set(languages)]});
  else {
    if (description.length > existing.description.length) existing.description = description;
    existing.languages = [...new Set([...existing.languages, ...languages])];
  }
}
return [...byName.values()].map(repo => ({
  json: {
    ...repo,
    text: [
      `Repository: ${repo.name}`,
      `Description: ${repo.description || ''}`,
      `Languages: ${repo.languages.join(', ')}`
    ].join('\n')
  }
}));

const repositories = $input.all().map(item => ({
  name: item.json.name,
  description: item.json.description,
  languages: item.json.languages
}));
return [{
  json: {
    statement: `
      UNWIND $repositories AS repo
      MERGE (r:Repository {name: repo.name})
      SET r.description = repo.description,
          r.languages = repo.languages
      WITH r, repo
      UNWIND repo.languages AS language
      MERGE (l:Language {name: language})
      MERGE (r)-[:USES_LANGUAGE]->(l)
      RETURN count(DISTINCT r) AS repositoriesProcessed
    `,
    parameters: { repositories }
  }
}];

// Use the same normalized records directly; no Neo4j read-back or merge needed.
return $input.all().map(item => ({
  json: {
    name: item.json.name,
    description: item.json.description,
    languages: item.json.languages,
    text: item.json.text
  }
}));

const sourceItems = $('Vector RAG - Prepare Embedding Input').all();
const embeddingItems = $input.all();
if (sourceItems.length !== embeddingItems.length) {
  throw new Error(`Repository/embedding count mismatch: ${sourceItems.length} vs ${embeddingItems.length}`);
}
return sourceItems.map((source, index) => {
  const repo = source.json;
  const response = embeddingItems[index].json;
  const embedding = response.embeddings?.[0] ?? response.body?.embeddings?.[0];
  if (!Array.isArray(embedding)) {
    throw new Error(`No embedding returned for ${repo.name}`);
  }
  if (embedding.length !== 768) {
    throw new Error(`Expected 768 dimensions for ${repo.name}; got ${embedding.length}`);
  }
  return {json: {name: repo.name, embedding}};
});

return $input.all().map(item => ({
  json: {
    statement: `
      MATCH (r:Repository {name: $name})
      SET r.embedding = $embedding
      RETURN r.name AS name, size(r.embedding) AS dimensions
    `,
    parameters: {
      name: item.json.name,
      embedding: item.json.embedding
    }
  }
}));
